CREATE TABLE identities (id text PRIMARY KEY, singleton integer NOT NULL DEFAULT 1 CHECK(singleton = 1), payload jsonb NOT NULL);
CREATE UNIQUE INDEX identity_singleton ON identities(singleton);
CREATE TABLE interests (id text PRIMARY KEY, identity_id text NOT NULL REFERENCES identities(id), created_at timestamptz NOT NULL, payload jsonb NOT NULL);
CREATE TABLE people (id text PRIMARY KEY, identity_id text NOT NULL REFERENCES identities(id), created_at timestamptz NOT NULL, payload jsonb NOT NULL);
CREATE TABLE person_interests (person_id text NOT NULL REFERENCES people(id) ON DELETE CASCADE, interest_id text NOT NULL REFERENCES interests(id), UNIQUE(person_id, interest_id));
CREATE TABLE conversations (id text PRIMARY KEY, person_id text NOT NULL REFERENCES people(id) ON DELETE CASCADE, created_at timestamptz NOT NULL, payload jsonb NOT NULL);
CREATE TABLE claims (id text PRIMARY KEY, person_id text NOT NULL REFERENCES people(id) ON DELETE CASCADE, conversation_id text REFERENCES conversations(id) ON DELETE CASCADE, interest_id text REFERENCES interests(id) ON DELETE SET NULL, created_at timestamptz NOT NULL, payload jsonb NOT NULL);
CREATE TABLE research_runs (id text PRIMARY KEY, interest_id text NOT NULL REFERENCES interests(id) ON DELETE CASCADE, status text NOT NULL CHECK(status IN ('queued','running','completed','failed')), created_at timestamptz NOT NULL, payload jsonb NOT NULL);
CREATE UNIQUE INDEX active_research_run ON research_runs(interest_id) WHERE status IN ('queued','running');
CREATE TABLE research_facts (id text PRIMARY KEY, interest_id text NOT NULL REFERENCES interests(id) ON DELETE CASCADE, run_id text NOT NULL REFERENCES research_runs(id) ON DELETE CASCADE, dedup_key text NOT NULL, effective_at timestamptz NOT NULL, created_at timestamptz NOT NULL, payload jsonb NOT NULL, UNIQUE(interest_id,dedup_key));
CREATE TABLE decks (id text PRIMARY KEY, person_id text NOT NULL REFERENCES people(id) ON DELETE CASCADE, fingerprint text NOT NULL, status text NOT NULL CHECK(status IN ('queued','running','completed','failed')), created_at timestamptz NOT NULL, snapshot jsonb NOT NULL, payload jsonb NOT NULL);
CREATE UNIQUE INDEX active_deck ON decks(person_id,fingerprint) WHERE status IN ('queued','running');
CREATE TABLE cards (id text PRIMARY KEY, deck_id text NOT NULL REFERENCES decks(id) ON DELETE CASCADE, position integer NOT NULL CHECK(position >= 0), payload jsonb NOT NULL, UNIQUE(deck_id,position));
CREATE TABLE jobs (id text PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('research','deck','claim_check')), entity_id text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','completed','failed')), attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, worker_id text, last_error text, UNIQUE(kind,entity_id));
CREATE INDEX job_poll ON jobs(status,available_at);
CREATE INDEX interests_page ON interests(created_at,id);
CREATE INDEX people_page ON people(created_at,id);
CREATE INDEX conversations_page ON conversations(person_id,created_at,id);
CREATE INDEX claims_page ON claims(person_id,created_at,id);
CREATE INDEX runs_page ON research_runs(interest_id,created_at,id);
CREATE INDEX facts_page ON research_facts(interest_id,created_at,id);
CREATE INDEX decks_page ON decks(person_id,created_at,id);
